@pytest.mark.parametrize('leading', [0,1,3])
def test_observed_records(leading):
    events=[]
    def app(environ,start_response):
        def body():
            try:
                for _ in range(leading): yield b''
                start_response('202 Accepted',[('Content-Type','text/plain'),('X-Mode','lazy')])
                events.append(environ['PATH_INFO'])
                yield b'first'; yield b''; yield b'last'
            finally: events.append('closed')
        return body()
    with httpx.Client(transport=httpx.WSGITransport(app),base_url='http://case.invalid',trust_env=False) as client:
        response=client.get('[EXTERNAL]/lazy')
    assert response.status_code==202 and response.headers['x-mode']=='lazy'
    assert response.content==b'firstlast' and events==['[EXTERNAL]/lazy','closed']

def _send_handling_auth(
    self,
    request: Request,
    auth: Auth,
    follow_redirects: bool,
    history: list[Response],
) -> Response:
    auth_flow = auth.sync_auth_flow(request)
    try:
        request = next(auth_flow)

        while True:
            response = self._send_handling_redirects(
                request,
                follow_redirects=follow_redirects,
                history=history,
            )
            try:
                try:
                    next_request = auth_flow.send(response)
                except StopIteration:
                    return response

                response.history = list(history)
                response.read()
                request = next_request
                history.append(response)

            except BaseException as exc:
                response.close()
                raise exc
    finally:
        auth_flow.close()

def _send_handling_redirects(
    self,
    request: Request,
    follow_redirects: bool,
    history: list[Response],
) -> Response:
    while True:
        if len(history) > self.max_redirects:
            raise TooManyRedirects(
                "Exceeded maximum allowed redirects.", request=request
            )

        for hook in self._event_hooks["request"]:
            hook(request)

        response = self._send_single_request(request)
        try:
            for hook in self._event_hooks["response"]:
                hook(response)
            response.history = list(history)

            if not response.has_redirect_location:
                return response

            request = self._build_redirect_request(request, response)
            history = history + [response]

            if follow_redirects:
                response.read()
            else:
                response.next_request = request
                return response

        except BaseException as exc:
            response.close()
            raise exc

